from torch import nn
import torch
import numpy as np
import os
from scipy.io import loadmat

class ADMMBase(nn.Module):
    def __init__(self,mat_dim = 6,input_dim = 2,num_steps:int=10,problem_parameters:dict={}):
        super().__init__()
        # set the datatype of the parameters to be uniform in the whole network
        self.dtypus = problem_parameters['dtype']
        self.N = problem_parameters['N']
        self.m = problem_parameters['m']
        self.n = problem_parameters['n']
        # load the dpc files generated by matlab
        to_load = 'QP_parameters_SS.mat'
        own_dic = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
        dpc_parameters = loadmat(os.path.join(own_dic,f'mat_files_{self.N}',to_load))        
        self.n_regios = num_steps
        # Setup the gradients
        G =  dpc_parameters['G']
        H = dpc_parameters['H']
        AA = dpc_parameters['Kx']
        BB = dpc_parameters['Ku']
        Hinv = np.linalg.inv(H)
        E = dpc_parameters['E']
        F = dpc_parameters['F']
        d = dpc_parameters['d']
        Uz = d[0:Hinv.shape[0],0]
        Lz = d[Hinv.shape[0]:,0]
        # a_std = 1/np.max(np.linalg.eigh(H).eigenvalues)
        eigs = np.linalg.eigh(H).eigenvalues
        tol =1e-3
        alphar = 0.2
        a_std = np.sqrt((np.max(eigs[eigs>tol])**(alphar))*(np.min(eigs[eigs>tol])**(1-alphar)))
        # in case the eigenvalues are too big, f(x) = softplus^-1(x) is approximately f(x)= x
        a_in = np.log(np.exp(a_std)-1)
        self.dual_n_steps = 1
        M = np.linalg.pinv(H+a_std*np.eye(H.shape[0]))
        GGT = G@G.T
        a_ggt = 1/np.max(np.linalg.eigh(GGT).eigenvalues)
        self.M1 =   nn.ParameterList(nn.Parameter(torch.tensor(M,  dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.M2 =   nn.ParameterList(nn.Parameter(torch.tensor(-M@F,  dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.rhos = nn.ParameterList(nn.Parameter(torch.tensor(a_in, dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.G_implicit = nn.Parameter(torch.tensor(-Hinv@F,  dtype=self.dtypus),requires_grad= True)
        self.h_implicit = nn.Parameter(torch.zeros(M.shape[0],  dtype=self.dtypus),requires_grad= True)
        self.register_buffer('Hinv',   torch.tensor(Hinv, dtype = self.dtypus))
        self.register_buffer('GGT',    torch.tensor(GGT  ,dtype = self.dtypus))
        self.register_buffer('a_G',    torch.tensor(a_ggt,dtype = self.dtypus))
        self.register_buffer('AA',     torch.tensor(AA,   dtype = self.dtypus))
        self.register_buffer('BB',     torch.tensor(BB,   dtype = self.dtypus))
        self.register_buffer('d',      torch.tensor(d,    dtype = self.dtypus))
        self.register_buffer('E',      torch.tensor(E,    dtype = self.dtypus))
        self.register_buffer('F_final',torch.tensor(F,    dtype = self.dtypus))
        self.register_buffer('H_final',torch.tensor(H,    dtype = self.dtypus))
        self.register_buffer('G',      torch.tensor(G,    dtype = self.dtypus))
        self.register_buffer('Lz',     torch.tensor(Lz,   dtype = self.dtypus))
        self.register_buffer('Uz',     torch.tensor(Uz,   dtype = self.dtypus))
        return

    def condensed_to_uncondensed(self,x0:torch.Tensor,U:torch.Tensor):
        '''
        U:  (B, N*m)
        x0: (B, n)
        AA: ((N+1)*n, n)
        BB: ((N+1)*n, N*m)

        returns:
            z_uncondensed: (B, N*(m+n))
            X_traj:        (B, N+1, n)
            U_traj:        (B, N, m)
        '''
        AA = self.AA.to(x0)
        BB = self.BB.to(x0)
        # Erwartet: U.shape == (B, N*m, T)
        B_batch = x0.shape[0]
        T = U.shape[2]
        X0_part = x0 @ AA.T                      # (B, (N+1)*n)
        X = X0_part.unsqueeze(-1) + torch.einsum(
            'ij,bjt->bit',
            BB,
            U
        )                                        # (B, (N+1)*n, T)
        U_traj = U.reshape(B_batch, self.N, self.m, T)
        X_traj = X.reshape(B_batch, self.N + 1, self.n, T)
        z_full = torch.cat(
            [U_traj, X_traj[:, 1:, :, :]],
            dim=2
        )                                        # (B, N, m+n, T)
        z_full = z_full.reshape(B_batch, self.N * (self.m + self.n), T)
        return z_full, X_traj, U_traj
    
    def dual_pgd(self, GGT,G, g,a_G = 1e-2,lam0=None):
        '''
        Calculate the 
        G:   (n_cons, z_dim)
        GGT: (n_cons, n_cons)  = G @ G.T
        g:   (B, z_dim)
        →   lam: (B, n_cons)
        '''
        B = g.shape[0]
        n_cons = G.shape[0]
        
        # Step size: 1 / max_eig(GGT)
        # if eta is None:
        #     eigmax = torch.linalg.eigvalsh(GGT).max()
        #     eta = 1.0 / (eigmax + 1e-8)
        
        Gg = g @ self.G.T                        # (B, n_cons)
        if lam0 is None:
            lam = torch.zeros(B, n_cons, device=g.device, dtype=g.dtype)
        else:
            lam = lam0
        for _ in range(self.dual_n_steps):
            grad = (lam @ GGT.T + Gg)  # (B, n_cons)
            lam = torch.relu(lam - a_G * grad)
        return lam

    def forward(self, xy: torch.Tensor):
        Hinv = self.Hinv.to(xy)
        G    = self.G.to(xy)
        GGT  = self.GGT.to(xy)
        E    = self.E.to(xy)
        F_final    = self.F_final.to(xy)
        H_final    = self.H_final.to(xy)
        d    = self.d.to(xy)
        Lz   = self.Lz.to(xy)
        Uz   = self.Uz.to(xy)
        a_G  = self.a_G.to(xy)
        
        # Standard ADMM scheme:
        batch_size = xy.shape[0]
        
        lam_shape = G.shape[0]
        z_shape = G.shape[1]
        yk    = xy@self.G_implicit.T + self.h_implicit #torch.zeros((batch_size,z_shape), device=xy.device, dtype=xy.dtype)
        zk    = torch.clamp(xy@self.G_implicit.T + self.h_implicit,min=-Lz,max=Uz) #torch.zeros((batch_size,z_shape), device=xy.device, dtype=xy.dtype)
        muk   = torch.zeros((batch_size,z_shape), device=xy.device, dtype=xy.dtype)
        lam_k = torch.zeros((batch_size,lam_shape) ,device = xy.device, dtype = xy.dtype)   # (batch, lam_dim)
        y_list   = [yk]
        z_list   = [zk]
        mu_list  = [muk]
        lam_list = [lam_k]
        for j in range(0,self.n_regios):
            rhok = torch.nn.functional.softplus(self.rhos[j])
            # Update first variable
            M1_sym = 0.5*(self.M1[j]+self.M1[j].T)
            ykp1  =   (rhok*zk - muk)@M1_sym + xy@self.M2[j].T
            # Update second variable
            zkp1 = torch.clamp(input= ykp1 + (1/rhok)*muk,min=-Lz,max=Uz)
            # Update dual variable
            mukp1 = muk + rhok*(ykp1-zkp1)

            y_list.append(ykp1)
            z_list.append(zkp1)
            mu_list.append(mukp1)
            
            g = zkp1 @ H_final + xy @ F_final.T
            # Estimate lambda
            lam_k = self.dual_pgd(GGT=GGT,G=G,g=g,a_G=a_G).to(xy)
            lam_list.append(lam_k)

            yk = ykp1
            zk = zkp1
            muk = mukp1

        y_stck = torch.stack(y_list, dim=-1)
        z_stck = torch.stack(z_list, dim=-1)
        mu_stck= torch.stack(mu_list, dim=-1)
        lam = torch.stack(lam_list, dim=-1)
        return z_stck,y_stck,lam